class Solution:
    def maximumInvitations(self, grid):
        m, n = len(grid), len(grid[0])
        match = [-1] * n

        def bt(i):
            if i == m:
                return 0
            best = bt(i + 1)
            for j in range(n):
                if grid[i][j] == 1 and match[j] == -1:
                    match[j] = i
                    best = max(best, 1 + bt(i + 1))
                    match[j] = -1
            return best

        return bt(0)

