        m, n = len(grid), len(grid[0])
        match = [-1] * n

        def dfs(i, visited):
            for j in range(n):
                if grid[i][j] == 1 and j not in visited:
                    visited.add(j)
                    if match[j] == -1 or dfs(match[j], visited):
                        match[j] = i
                        return True
            return False

        ans = 0
        for i in range(m):
            if dfs(i, set()):
                ans += 1
        return ans

