class Solution {
public:
    int n;
    vector<vector<int>> g;
    vector<int> matchOf;
    vector<bool> seen;

    bool dfs(int i) {
        for (int j = 0; j < n; j++) {
            if (g[i][j] == 1 && !seen[j]) {
                seen[j] = true;
                if (matchOf[j] == -1 || dfs(matchOf[j])) {
                    matchOf[j] = i;
                    return true;
                }
            }
        }
        return false;
    }

    int maximumInvitations(vector<vector<int>>& grid) {
        g = grid;
        int m = g.size();
        n = g[0].size();
        matchOf.assign(n, -1);
        int ans = 0;
        for (int i = 0; i < m; i++) {
            seen.assign(n, false);
            if (dfs(i)) ans++;
        }
        return ans;
    }
};

